class n{constructor(){this.rows=[{ja:"リーフレタス",en:"Lettuce",growth:.62,seconds:180},{ja:"小松菜",en:"Mustard greens",growth:.35,seconds:240},{ja:"バジル",en:"Basil",growth:.15,seconds:300}],this.tendCooldown=0}get ready(){return this.rows.filter(o=>o.growth>=1).length}update(o){this.tendCooldown=Math.max(0,this.tendCooldown-o);for(const t of this.rows)t.growth=Math.min(1,t.growth+Math.max(0,o)/t.seconds)}tend(){if(!(this.tendCooldown>0)){for(const o of this.rows)o.growth=Math.min(1,o.growth+.04);this.tendCooldown=30}}harvest(o){let t=0;for(const r of this.rows)r.growth<1||o.supplies.food>=o.capacity.food||(o.supplies.food++,r.growth=.05,t++);return t}}export{n as P};
